import { Component, input, model } from '@angular/core';
import { NzDrawerModule } from 'ng-zorro-antd/drawer';

/** hrm-drawer — panel trượt. [(open)] two-way. Nội dung qua content.
 *  <hrm-drawer [(open)]="show" title="Chi tiết">...</hrm-drawer> */
@Component({
  selector: 'hrm-drawer',
  imports: [NzDrawerModule],
  template: `
    <nz-drawer
      [nzVisible]="open()"
      [nzTitle]="title()"
      [nzWidth]="width()"
      [nzPlacement]="placement()"
      [nzClosable]="closable()"
      (nzOnClose)="open.set(false)">
      <ng-container *nzDrawerContent><ng-content /></ng-container>
    </nz-drawer>
  `,
  host: { class: 'hrm-drawer' },
})
export class HrmDrawer {
  readonly open = model(false);
  readonly title = input('');
  readonly width = input(378);
  readonly placement = input<'left' | 'right' | 'top' | 'bottom'>('right');
  readonly closable = input(true);
}
